n0:createOracleFunction.n0:source:
CREATE OR REPLACE EDITIONABLE FUNCTION "%USER_NAME%"."GET_TIME_LENGTH_DISPLAY" (p_time_length_id number)
    return varchar2 
as
    l_time_length_display session_length.time_length_display%type;
begin
    select time_length_display
    into l_time_length_display
    from session_length
    where to_number(time_length_id) = p_time_length_id;

    return l_time_length_display;

exception
    when others then
        return null;
end;
/
